namespace CryptoBase.SpeedTest.Workloads;

/// <summary>
/// Fixed RSA private keys, so that the signature workloads need not generate keys at start-up.
/// </summary>
/// <remarks>
/// For measuring speed only: these keys are public and must never protect anything. They were generated with <c>RsaKey.GenerateKey</c>
/// and exported with <c>ExportPkcs8PrivateKey</c>, as PKCS #8 in Base64.
/// </remarks>
internal static class RsaTestKeys
{
	private const string Rsa2048 = "";

	private const string Rsa3072 = "";

	private const string Rsa4096 = "";

	public static byte[] GetPkcs8PrivateKey(int modulusBits)
	{
		return Convert.FromBase64String
		(
			modulusBits switch
			{
				2048 => Rsa2048,
				3072 => Rsa3072,
				4096 => Rsa4096,
				_ => throw new ArgumentOutOfRangeException(nameof(modulusBits), modulusBits, null)
			}
		);
	}
}
